1	//! Translate core `Item`s into Gemini `contents` + `systemInstruction`.
2	
3	use paigasus_helikon_core::{ContentPart, Item, MediaSource, ModelError};
4	use serde_json::{json, Value};
5	use std::collections::HashSet;
6	
7	/// `contents` + optional `systemInstruction`.
8	pub(crate) struct TranslatedContents {
9	    pub(crate) system: Option<Value>,
10	    pub(crate) contents: Vec<Value>,
11	}
12	
13	/// Tracks tool calls that have no result yet, so each result takes its name
14	/// from the earliest open call with the same id (FIFO). Gemini ids are only
15	/// unique within one response, so ids can repeat across turns.
16	struct OpenCalls<'a> {
17	    /// `(call_id, name)` in open order.
18	    open: Vec<(&'a str, &'a str)>,
19	    /// Ids opened so far.
20	    seen: HashSet<&'a str>,
21	    /// Ids of every call in the conversation (error-message choice only).
22	    all: HashSet<&'a str>,
23	}
24	
25	impl<'a> OpenCalls<'a> {
26	    fn new(items: &'a [Item]) -> Self {
27	        let mut all = HashSet::new();
28	        for it in items {
29	            match it {
30	                Item::ToolCall { call_id, .. } => {
31	                    all.insert(call_id.as_str());
32	                }
33	                Item::AssistantMessage { content, .. } => {
34	                    for p in content {
35	                        if let ContentPart::ToolUse { call_id, .. } = p {
36	                            all.insert(call_id.as_str());
37	                        }
38	                    }
39	                }
40	                _ => {}
41	            }
42	        }
43	        Self {
44	            open: Vec::new(),
45	            seen: HashSet::new(),
46	            all,
47	        }
48	    }
49	
50	    fn open(&mut self, call_id: &'a str, name: &'a str) {
51	        self.seen.insert(call_id);
52	        self.open.push((call_id, name));
53	    }
54	
55	    /// `Ok(Some(name))` closes the earliest open call with this id. `Ok(None)`
56	    /// means a duplicate result: the caller drops it.
57	    fn close(&mut self, call_id: &str) -> Result<Option<&'a str>, ModelError> {
58	        if let Some(pos) = self.open.iter().position(|(id, _)| *id == call_id) {
59	            return Ok(Some(self.open.remove(pos).1));
60	        }
61	        if self.seen.contains(call_id) {
62	            tracing::warn!(
63	                target: "paigasus::gemini::translate",
64	                call_id,
65	                "tool result closes no open call; dropping"
66	            );
67	            return Ok(None);
68	        }
69	        if self.all.contains(call_id) {
70	            Err(ModelError::Other(anyhow::anyhow!(
71	                "tool result for call_id {call_id} comes before its call"
72	            )))
73	        } else {
74	            Err(ModelError::Other(anyhow::anyhow!(
75	                "tool result references unknown call_id {call_id}"
76	            )))
77	        }
78	    }
79	}
80	
81	/// Translate core items into Gemini `contents`. Returns an error on an empty
82	/// or system-only conversation (Gemini 400s on empty contents).
83	pub(crate) fn items_to_contents(items: &[Item]) -> Result<TranslatedContents, ModelError> {
84	    let mut calls = OpenCalls::new(items);
85	    let mut system_parts: Vec<Value> = Vec::new();
86	    let mut entries: Vec<(&'static str, Vec<Value>)> = Vec::new();
87	
88	    for it in items {
89	        match it {
90	            Item::System { content } => {
91	                system_parts.extend(text_parts(content));
92	            }
93	            Item::UserMessage { content } => {
94	                entries.push(("user", user_parts(content, &mut calls)?));
95	            }
96	            Item::AssistantMessage { content, .. } => {
97	                for p in content {
98	                    if let ContentPart::ToolUse { call_id, name, .. } = p {
99	                        calls.open(call_id, name);
100	                    }
101	                }
102	                entries.push(("model", assistant_parts(content)));
103	            }
104	            Item::ToolCall {
105	                call_id,
106	                name,
107	                args,
108	            } => {
109	                calls.open(call_id, name);
110	                entries.push((
111	                    "model",
112	                    vec![json!({ "functionCall": { "id": call_id, "name": name, "args": args } })],
113	                ));
114	            }
115	            Item::ToolResult { call_id, content } => {
116	                if let Some(name) = calls.close(call_id)? {
117	                    entries.push((
118	                        "user",
119	                        vec![json!({
120	                            "functionResponse": {
121	                                "id": call_id,
122	                                "name": name,
123	                                "response": tool_response_object(content),
124	                            }
125	                        })],
126	                    ));
127	                }
128	            }
129	            _ => {}
130	        }
131	    }
132	
133	    let contents = merge_same_role(entries);
134	    if contents.is_empty() {
135	        return Err(ModelError::Other(anyhow::anyhow!(
136	            "gemini request has no user/model turns (empty or system-only conversation)"
137	        )));
138	    }
139	
140	    let system = (!system_parts.is_empty()).then(|| json!({ "parts": system_parts }));
141	    Ok(TranslatedContents { system, contents })
142	}
143	
144	/// Merge adjacent entries of the same role into one content, in order.
145	///
146	/// Two `user` entries merge only when both hold only `functionResponse` parts
147	/// or both hold none. Gemini 3 starts the current turn at the last `user`
148	/// content that is not a tool result, and it checks thought signatures only in
149	/// that turn. The SDK sends no signatures yet (SMA-827). A text and a
150	/// `functionResponse` in one content would keep the unsigned `functionCall` in
151	/// the current turn, and Gemini would return HTTP 400. A content that mixes
152	/// results and other parts merges with nothing, so a later text never joins a
153	/// tool result.
154	/// An entry with no parts is dropped first, so it never emits `"parts": []`.
155	fn merge_same_role(entries: Vec<(&'static str, Vec<Value>)>) -> Vec<Value> {
156	    #[derive(PartialEq, Clone, Copy)]
157	    enum Class {
158	        AllResponses,
159	        NoResponses,
160	        Mixed,
161	    }
162	    let class = |parts: &[Value]| {
163	        let n = parts
164	            .iter()
165	            .filter(|p| p.get("functionResponse").is_some())
166	            .count();
167	        if n == parts.len() {
168	            Class::AllResponses
169	        } else if n == 0 {
170	            Class::NoResponses
171	        } else {
172	            Class::Mixed
173	        }
174	    };
175	    // Each merged entry keeps its class, so a merge never rescans the parts.
176	    let mut merged: Vec<(&'static str, Class, Vec<Value>)> = Vec::new();
177	    for (role, parts) in entries {
178	        if parts.is_empty() {
179	            continue;
180	        }
181	        let incoming = class(&parts);
182	        match merged.last_mut() {
183	            // A merge needs equal classes that are not `Mixed`, so the stored
184	            // class stays correct after it.
185	            Some((last_role, last_class, last_parts))
186	                if *last_role == role
187	                    && (role != "user"
188	                        || (*last_class != Class::Mixed && *last_class == incoming)) =>
189	            {
190	                last_parts.extend(parts)
191	            }
192	            _ => merged.push((role, incoming, parts)),
193	        }
194	    }
195	    merged
196	        .into_iter()
197	        .map(|(role, _, parts)| json!({ "role": role, "parts": parts }))
198	        .collect()
199	}
200	
201	fn text_parts(content: &[ContentPart]) -> Vec<Value> {
202	    content
203	        .iter()
204	        .filter_map(|p| match p {
205	            ContentPart::Text { text } => Some(json!({ "text": text })),
206	            _ => None,
207	        })
208	        .collect()
209	}
210	
211	/// Translate the parts of an `Item::UserMessage`.
212	///
213	/// Handles the Anthropic-native [`ContentPart::ToolResult`] shape (a tool
214	/// result carried inside a user turn) by emitting a `functionResponse` part,
215	/// recovering the function name from the earliest open call with that id
216	/// exactly like the top-level [`Item::ToolResult`] branch. A duplicate result
217	/// (no open call left) is dropped with a warning. Text and base64 images translate as usual;
218	/// URL images and other parts are dropped with a discriminant warning.
219	fn user_parts<'a>(
220	    content: &'a [ContentPart],
221	    calls: &mut OpenCalls<'a>,
222	) -> Result<Vec<Value>, ModelError> {
223	    let mut out = Vec::new();
224	    for p in content {
225	        match p {
226	            // The translator drops empty text, as SMA-804 spec section 5.3
227	            // asks every translator to do.
228	            ContentPart::Text { text } if text.is_empty() => {}
229	            ContentPart::Text { text } => out.push(json!({ "text": text })),
230	            ContentPart::Image {
231	                source: MediaSource::Base64 { mime_type, data },
232	            } => {
233	                out.push(json!({ "inlineData": { "mimeType": mime_type, "data": data } }));
234	            }
235	            ContentPart::ToolResult { call_id, content } => {
236	                if let Some(name) = calls.close(call_id)? {
237	                    out.push(json!({
238	                        "functionResponse": {
239	                            "id": call_id,
240	                            "name": name,
241	                            "response": tool_response_object(content),
242	                        }
243	                    }));
244	                }
245	            }
246	            other => {
247	                tracing::warn!(
248	                    target: "paigasus::gemini::translate",
249	                    part = ?std::mem::discriminant(other),
250	                    "unsupported content part; skipping"
251	                );
252	            }
253	        }
254	    }
255	    Ok(out)
256	}
257	
258	fn assistant_parts(content: &[ContentPart]) -> Vec<Value> {
259	    let mut out = Vec::new();
260	    for p in content {
261	        match p {
262	            ContentPart::Text { text } if text.is_empty() => {}
263	            ContentPart::Text { text } => out.push(json!({ "text": text })),
264	            ContentPart::ToolUse {
265	                call_id,
266	                name,
267	                args,
268	            } => {
269	                out.push(json!({ "functionCall": { "id": call_id, "name": name, "args": args } }));
270	            }
271	            ContentPart::Reasoning { .. } => { /* deferred (D3) */ }
272	            other => {
273	                tracing::warn!(
274	                    target: "paigasus::gemini::translate",
275	                    part = ?std::mem::discriminant(other),
276	                    "unsupported assistant part; skipping"
277	                );
278	            }
279	        }
280	    }
281	    out
282	}
283	
284	/// Reduce a tool result's content parts to a JSON object for `functionResponse.response`.
285	fn tool_response_object(content: &[ContentPart]) -> Value {
286	    let text: String = content
287	        .iter()
288	        .filter_map(|p| match p {
289	            ContentPart::Text { text } => Some(text.as_str()),
290	            _ => None,
291	        })
292	        .collect::<Vec<_>>()
293	        .join("");
294	    match serde_json::from_str::<Value>(&text) {
295	        Ok(Value::Object(m)) => Value::Object(m),
296	        Ok(other) => json!({ "result": other }),
297	        Err(_) => json!({ "result": text }),
298	    }
299	}
