880	    /// Observe one [`crate::AgentEvent`] from the run's stream: record the
881	    /// semantic items (assistant messages, tool calls, tool results, handoffs)
882	    /// and track the active agent from `RunStarted` / `AgentUpdated`.
883	    pub fn observe(&mut self, event: &AgentEvent) {
884	        match event {
885	            AgentEvent::RunStarted { agent } | AgentEvent::AgentUpdated { agent } => {
886	                self.current_agent = agent.clone();
887	            }
888	            AgentEvent::TurnStarted { .. } => {
889	                self.in_resume_window = false;
890	            }
891	            AgentEvent::RunFailed { .. } if self.in_resume_window && !self.has_resume_result() => {
892	                self.resume_rejected = true;
893	            }
894	            AgentEvent::MessageOutput {
895	                item: Item::AssistantMessage { content, agent },
896	            } => {
897	                let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
898	                self.events
899	                    .push(SessionEvent::assistant_message(content.clone(), name));
900	            }
901	            AgentEvent::ToolCallItem {
902	                item:
903	                    Item::ToolCall {
904	                        call_id,
905	                        name,
906	                        args,
907	                    },
908	            } => {
909	                self.events.push(SessionEvent::tool_called(
910	                    call_id.clone(),
911	                    name.clone(),
912	                    args.clone(),
913	                ));
914	            }
915	            AgentEvent::ToolOutputItem {
916	                item: Item::ToolResult { call_id, content },
917	            } => {
918	                let event = SessionEvent::tool_returned(call_id.clone(), content.clone());
919	                if self.in_resume_window {
920	                    self.resume_block.push(event);
921	                } else {
922	                    self.events.push(event);
923	                }
924	            }
925	            AgentEvent::HandoffItem { from, to } => {
926	                self.events
927	                    .push(SessionEvent::handoff_occurred(from.clone(), to.clone()));
928	            }
929	            AgentEvent::RunDeferred { calls, .. } => {
930	                let mut warned = false;
931	                for call in calls {
932	                    let raw = self
933	                        .deferral_slot
934	                        .as_ref()
935	                        .and_then(|slot| slot.take(call.deferral_id()));
936	                    match raw {
937	                        Some(raw) => self.events.push(SessionEvent::tool_deferred(&raw)),
938	                        None => {
939	                            if !warned {
940	                                warned = true;
941	                                tracing::warn!(
942	                                    target: "paigasus::core::session",
943	                                    "RunDeferred call has no raw arguments in the deferral slot; recording the event copy, whose arguments can be redacted"
944	                                );
945	                            }
946	                            self.events.push(SessionEvent::tool_deferred(call));
947	                        }
948	                    }
949	                }
950	            }
951	            AgentEvent::UserMessageInjected { content } => {
952	                self.events
953	                    .push(SessionEvent::user_message(content.clone()));
954	            }
955	            _ => {}
956	        }
957	    }
