406	    /// Drain the stream and aggregate into a `RunResult<String>`.
407	    ///
408	    /// `final_output` is the concatenated text from the *last*
409	    /// `AgentEvent::MessageOutput { item: AssistantMessage }`. In multi-turn
410	    /// flows, each new assistant message resets `final_output`, ensuring
411	    /// the result is the terminal assistant output, not intermediate text.
412	    /// Structured-output callers go through `RunResult::<String>::parse_final::<T>()`
413	    /// (SMA-313).
414	    ///
415	    /// A terminal `AgentEvent::RunDeferred` sets `stop_reason` to
416	    /// `StopReason::Deferred`, and a terminal `AgentEvent::RunStopped` sets it
417	    /// to `StopReason::Stopped`. Both return `Ok` with the usage of the
418	    /// terminal event, unless the runner recorded a failed strict session write
419	    /// (see [`RunResultStreaming::with_session_write`]). A recorded write error
420	    /// wins: `collect` then returns `Err(RunError::SessionWrite)`.
421	    pub async fn collect(mut self) -> Result<RunResult, RunError> {
422	        use futures_util::stream::StreamExt;
423	        let mut events = Vec::new();
424	        let mut final_output = String::new();
425	        let mut usage = crate::TokenUsage::default();
426	        let mut stop_reason = crate::StopReason::Completed;
427	        // Capture the RunFailed string but keep draining: state-machine failures
428	        // record their structured error AFTER yielding RunFailed, so the slot is
429	        // only guaranteed populated once the stream ends.
430	        let mut failed: Option<String> = None;
431	
432	        while let Some(ev) = self.events.next().await {
433	            match &ev {
434	                crate::AgentEvent::MessageOutput {
435	                    item: crate::Item::AssistantMessage { content, .. },
436	                } => {
437	                    final_output.clear();
438	                    for part in content {
439	                        if let crate::ContentPart::Text { text } = part {
440	                            final_output.push_str(text);
441	                        }
442	                    }
443	                }
444	                crate::AgentEvent::RunCompleted { usage: u } => usage = *u,
445	                crate::AgentEvent::RunDeferred { calls, usage: u } => {
446	                    usage = *u;
447	                    stop_reason = crate::StopReason::Deferred {
448	                        calls: calls.clone(),
449	                    };
450	                }
451	                crate::AgentEvent::RunStopped { reason, usage: u } => {
452	                    usage = *u;
453	                    stop_reason = crate::StopReason::Stopped {
454	                        reason: reason.clone(),
455	                    };
456	                }
457	                crate::AgentEvent::RunFailed { error } => {
458	                    failed = Some(error.clone());
459	                }
460	                _ => {}
461	            }
462	            events.push(ev);
463	        }
464	
465	        if let Some(e) = self.take_session_write() {
466	            return Err(RunError::SessionWrite(e));
467	        }
468	        if let Some(err_msg) = failed {
469	            if let Some(err) = self.failure.as_ref().and_then(FailureSlot::take) {
470	                return Err(RunError::Agent(err));
471	            }
472	            return Err(RunError::Other(anyhow::anyhow!(err_msg)));
473	        }
474	
475	        Ok(RunResult {
476	            final_output,
477	            events,
478	            usage,
479	            stop_reason,
480	        })
481	    }
