        let legacy = r#"{"agent_name":"a","conversation":[],"config":{"max_turns":4,"parallel_tool_call_limit":null},"timeout_ms":null}"#;
        let back: WorkflowInput = serde_json::from_str(legacy).expect("legacy deserialize");
