async fn invoke_clears_the_deferral_flag() {
    let server = AgentCoreServer::<()>::builder()
        .agent(std::sync::Arc::new(DeferralProbe))
        .context_provider(Arc::new(DeferringProvider))
        .build()
        .expect("server builds");

