1	//! Request and response data-transfer objects (DTOs).
2	//!
3	//! These are hand-rolled wire types that sit between HTTP and the core
4	//! [`paigasus_helikon_core`] types.  Core's [`AgentInput`] / [`AgentEvent`]
5	//! already derive `Serialize`/`Deserialize`, but they are not directly
6	//! suitable as HTTP bodies (e.g. `AgentInput` is `#[non_exhaustive]` with
7	//! constructor-only semantics).  The DTOs here bridge that gap.
8	
9	use paigasus_helikon_core::{AgentEvent, AgentInput, ContentPart, Item, TokenUsage};
10	use serde::{Deserialize, Serialize};
11	use uuid::Uuid;
12	
13	// ── RunRequest ────────────────────────────────────────────────────────────────
14	
15	/// Internal representation — not public; `RunRequest` wraps it.
16	enum RunRequestKind {
17	    Input(String),
18	    Messages(Vec<Item>),
19	}
20	
21	/// HTTP request body for a synchronous or async agent run.
22	///
23	/// Accepts **exactly one** of these JSON shapes:
24	/// - `{ "input": "<text>" }` — shorthand for a single user text message.
25	/// - `{ "messages": [ … ] }` — an explicit list of [`Item`]s (use when you
26	///   need multi-turn context or non-text content parts).
27	///
28	/// Supplying both keys, neither key, or any unknown field is rejected with a
29	/// deserialization error.
30	pub struct RunRequest(RunRequestKind);
31	
32	/// Private raw helper struct used by `RunRequest`'s custom `Deserialize`
33	/// implementation.
34	///
35	/// Unlike an `#[serde(untagged)]` enum — which silently drops a conflicting
36	/// extra field and ignores unknown keys (and is incompatible with
37	/// `deny_unknown_fields`) — this single struct with `deny_unknown_fields`
38	/// rejects unknown keys. The "exactly one of `input`/`messages`" rule is then
39	/// enforced by hand in [`RunRequest`]'s `Deserialize`.
40	#[derive(Deserialize)]
41	#[serde(deny_unknown_fields)]
42	struct RunRequestRaw {
43	    #[serde(default)]
44	    input: Option<String>,
45	    #[serde(default)]
46	    messages: Option<Vec<Item>>,
47	}
48	
49	impl<'de> Deserialize<'de> for RunRequest {
50	    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
51	    where
52	        D: serde::Deserializer<'de>,
53	    {
54	        let raw = RunRequestRaw::deserialize(deserializer)?;
55	        match (raw.input, raw.messages) {
56	            (Some(input), None) => Ok(RunRequest(RunRequestKind::Input(input))),
57	            (None, Some(messages)) => Ok(RunRequest(RunRequestKind::Messages(messages))),
58	            (Some(_), Some(_)) => Err(serde::de::Error::custom(
59	                "provide exactly one of `input` or `messages`, not both",
60	            )),
61	            (None, None) => Err(serde::de::Error::custom(
62	                "provide exactly one of `input` or `messages`",
63	            )),
64	        }
65	    }
66	}
67	
68	impl RunRequest {
69	    /// Convert this request into an [`AgentInput`] ready to pass to a runner.
70	    ///
71	    /// - The `input` form delegates to [`AgentInput::from_user_text`].
72	    /// - The `messages` form constructs an `AgentInput` from the supplied
73	    ///   item list.
74	    pub fn into_agent_input(self) -> AgentInput {
75	        match self.0 {
76	            RunRequestKind::Input(text) => AgentInput::from_user_text(text),
77	            RunRequestKind::Messages(messages) => {
78	                let mut input = AgentInput::new();
79	                input.messages = messages;
80	                input
81	            }
82	        }
83	    }
84	}
