88	/// Terminal outcome of an agent run.
89	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
90	#[serde(rename_all = "snake_case")]
91	#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
92	pub enum RunStatus {
93	    /// The run completed normally.
94	    Completed,
95	    /// The run finished with an error.
