99	// ── RunResponse ───────────────────────────────────────────────────────────────
100	
101	/// HTTP response body for a completed (non-streaming) agent run.
102	#[derive(Debug, Clone, Serialize)]
103	pub struct RunResponse {
104	    /// Unique identifier for this run, formatted as a UUID string.
105	    pub run_id: String,
106	    /// Terminal status of the run.
107	    pub status: RunStatus,
108	    /// Concatenated text of the last assistant [`Item::AssistantMessage`]
109	    /// emitted during the run.  `None` if the run produced no assistant output.
110	    pub output: Option<String>,
111	    /// Human-readable error message.  Present only when `status` is
112	    /// [`RunStatus::Failed`].
113	    pub error: Option<String>,
114	    /// Aggregated token usage across the run.  Present only when `status` is
115	    /// [`RunStatus::Completed`].
116	    pub usage: Option<TokenUsage>,
117	    /// All [`AgentEvent`]s emitted during the run, in order.
118	    pub events: Vec<AgentEvent>,
119	}
120	
121	impl RunResponse {
122	    /// Build a `RunResponse` by scanning `events` for the terminal event and
123	    /// the last assistant output.
124	    ///
125	    /// - The last [`AgentEvent::MessageOutput`] whose inner [`Item`] is an
126	    ///   [`Item::AssistantMessage`] is used to populate `output` (all
127	    ///   [`ContentPart::Text`] blocks are concatenated).
128	    /// - [`AgentEvent::RunCompleted`] sets `status = Completed` and captures
129	    ///   `usage`.
130	    /// - [`AgentEvent::RunStopped`] also sets `status = Completed`: a host stop
131	    ///   is a controlled end, not a failure.
132	    /// - [`AgentEvent::RunFailed`] sets `status = Failed` and captures
133	    ///   `error`.
134	    /// - If no terminal event is present, `status` defaults to `Failed`
135	    ///   (defensive).
136	    pub fn from_events(run_id: Uuid, events: Vec<AgentEvent>) -> Self {
137	        let mut output: Option<String> = None;
138	        let mut status = RunStatus::Failed;
139	        let mut error: Option<String> = None;
140	        let mut run_usage: Option<TokenUsage> = None;
141	
142	        for event in &events {
143	            match event {
144	                AgentEvent::MessageOutput {
145	                    item: Item::AssistantMessage { content, .. },
146	                } => {
147	                    let mut text = String::new();
148	                    for part in content {
149	                        if let ContentPart::Text { text: t } = part {
150	                            text.push_str(t);
151	                        }
152	                    }
153	                    if !text.is_empty() {
154	                        output = Some(text);
155	                    }
156	                }
157	                AgentEvent::RunCompleted { usage: u } => {
158	                    status = RunStatus::Completed;
159	                    run_usage = Some(*u);
160	                }
161	                // A host stop is a controlled end, not a failure. `RunStatus` has no
162	                // stopped value, so it reports as completed with the run usage.
163	                AgentEvent::RunStopped { usage: u, .. } => {
164	                    status = RunStatus::Completed;
165	                    run_usage = Some(*u);
166	                }
167	                AgentEvent::RunFailed { error: e } => {
168	                    status = RunStatus::Failed;
169	                    error = Some(e.clone());
170	                }
171	                _ => {}
172	            }
173	        }
174	
175	        Self {
176	            run_id: run_id.to_string(),
177	            status,
178	            output,
179	            error,
180	            usage: run_usage,
181	            events,
182	        }
183	    }
184	}
