fn live_count(evs: &[SessionEvent]) -> usize {
    let last_compacted = evs
        .iter()
        .rposition(|e| matches!(e, SessionEvent::Compacted { .. }));
    match last_compacted {
        Some(i) => evs.len() - i,
        None => evs.len(),
    }
}

