341	    /// Validate a resume request against the session log and make a plan.
342	    ///
343	    /// `events` is the full session log and `snapshot` is the session
344	    /// snapshot (a custom session can override the snapshot, so the runner
345	    /// reads both). `root_agent_name` is the name of the agent that the
346	    /// runner runs. `input` carries the host resolutions and the new input
347	    /// messages.
348	    ///
349	    /// The checks run in this order: tool items in the input, duplicate
350	    /// resolutions, no open deferrals, unknown deferral ids, unresolved
351	    /// deferrals, a session changed after the deferral, a deferred call that
352	    /// is not in the history, and a handoff path that is too deep.
353	    ///
354	    /// A `root_agent_name` that is not the first name of the handoff path is
355	    /// not an error. The agent then denies every call.
356	    pub fn from_events(
357	        events: &[crate::SessionEvent],
358	        snapshot: &crate::ConversationSnapshot,
359	        root_agent_name: &str,
360	        input: &crate::AgentInput,
361	        max_agent_depth: u32,
362	    ) -> Result<ResumePlan, InvalidResume> {
363	        use crate::{Item, SessionEvent};
364	
365	        // A nested `ContentPart::ToolUse` or `ContentPart::ToolResult` is
366	        // equal to a top-level tool item, so it is rejected too.
367	        let has_tool_part = |content: &[crate::ContentPart]| {
368	            content.iter().any(|p| {
369	                matches!(
370	                    p,
371	                    crate::ContentPart::ToolUse { .. } | crate::ContentPart::ToolResult { .. }
372	                )
373	            })
374	        };
375	        if input.messages.iter().any(|i| match i {
376	            Item::ToolCall { .. } | Item::ToolResult { .. } => true,
