78	impl Model for GeminiModel {
79	    async fn invoke(
80	        &self,
81	        request: ModelRequest,
82	        cancel: CancellationToken,
83	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
84	        let cfg = self.0.clone();
85	        let prepared = crate::translate::build_request(&cfg, &request)?;
86	        let url = stream_url(&cfg);
87	
88	        // Resolve the auth header up-front (async for Auth::Token), inside the
89	        // caller's await so a token-fetch failure returns Err from invoke.
90	        let (header_name, header_value) = match &cfg.auth {
91	            Auth::Token(p) => {
92	                let tok = tokio::select! {
93	                    biased;
94	                    _ = cancel.cancelled() => return Err(ModelError::Unavailable),
95	                    t = p.token() => t?,
96	                };
97	                (reqwest::header::AUTHORIZATION, format!("Bearer {tok}"))
98	            }
99	            other => auth_header(other)?,
100	        };
101	
102	        let client = cfg.http.clone();
103	        let body = prepared.body;
104	
105	        let s = stream! {
106	            let send_fut = client
107	                .post(&url)
108	                .header(header_name, header_value)
109	                .header(reqwest::header::CONTENT_TYPE, "application/json")
110	                .json(&body)
111	                .send();
112	
113	            let response = tokio::select! {
114	                biased;
115	                _ = cancel.cancelled() => return,
116	                r = send_fut => match r {
117	                    Ok(r) => r,
118	                    Err(e) => { yield Err(ModelError::Transport(e.to_string())); return; }
119	                },
120	            };
121	
122	            let status = response.status();
123	            if !status.is_success() {
124	                let retry_after_ms = parse_retry_after_ms(response.headers());
125	                let bytes = response.bytes().await.unwrap_or_default();
126	                let parsed: Result<serde_json::Value, _> = serde_json::from_slice(&bytes);
127	                let (sfield, message) = parsed
128	                    .as_ref()
129	                    .ok()
130	                    .map(|v| {
131	                        let s = v.get("error").and_then(|e| e.get("status")).and_then(|t| t.as_str()).unwrap_or("").to_owned();
132	                        let m = v.get("error").and_then(|e| e.get("message")).and_then(|t| t.as_str()).unwrap_or("").to_owned();
133	                        (s, m)
134	                    })
135	                    .unwrap_or_else(|| (String::new(), String::from_utf8_lossy(&bytes).into_owned()));
136	                yield Err(classify(status.as_u16(), Some(&sfield).filter(|s| !s.is_empty()).map(|s| s.as_str()), &message, retry_after_ms));
137	                return;
138	            }
139	
140	            let mut event_stream = response.bytes_stream().eventsource();
141	            let mut translator = StreamTranslator::new();
142	            loop {
143	                let next = tokio::select! {
144	                    biased;
145	                    _ = cancel.cancelled() => return,
146	                    n = event_stream.next() => n,
147	                };
148	                match next {
149	                    None => {
150	                        for ev in translator.finish() { yield ev; }
151	                        return;
152	                    }
153	                    Some(Err(e)) => { yield Err(ModelError::Transport(e.to_string())); return; }
154	                    Some(Ok(event)) => {
155	                        if event.data == "[DONE]" {
156	                            for ev in translator.finish() { yield ev; }
157	                            return;
158	                        }
159	                        let chunk: GeminiChunk = match serde_json::from_str(&event.data) {
160	                            Ok(c) => c,
161	                            Err(parse_err) => {
162	                                tracing::warn!(
163	                                    target: "paigasus::gemini::sse",
164	                                    %parse_err, event_len = event.data.len(),
165	                                    "unparseable SSE event payload"
166	                                );
167	                                continue;
168	                            }
169	                        };
170	                        for ev in translator.consume(chunk) {
171	                            let is_err = ev.is_err();
172	                            yield ev;
173	                            if is_err { return; }
174	                        }
175	                    }
176	                }
177	            }
178	        };
179	        Ok(Box::pin(s))
180	    }
