215	            },
216	            Item::ToolResult {
217	                call_id: "fc_1".into(),
218	                content: vec![ContentPart::Text {
219	                    text: "{\"n\":2}".into(),
220	                }],
221	            },
222	        ];
223	        let b = body(r);
224	        // The two parallel calls merge into one model content; the two
225	        // responses merge into one user content (SMA-820). Both carry the
226	        // real name "search" but distinct ids.
227	        assert_eq!(
