229	            "search"
230	        );
231	        assert_eq!(
232	            b["contents"][2]["parts"][0]["functionResponse"]["id"],
233	            "fc_0"
234	        );
235	        assert_eq!(
236	            b["contents"][2]["parts"][1]["functionResponse"]["id"],
237	            "fc_1"
238	        );
239	        insta::assert_json_snapshot!(b);
240	    }
