1	//! [`Vec<Item>`] → OpenAI Chat / Responses request messages.
2	//!
3	//! See SMA-316 spec § "Wire translation" for the rule table. Both backends
4	//! share many translation rules but the output JSON shape differs; we
5	//! build serde_json `Value`s directly rather than typed structs to keep
6	//! the test-fixture surface readable.
7	
8	use paigasus_helikon_core::{ContentPart, Item, MediaSource};
9	use serde_json::{json, Value};
10	
11	/// Translate a conversation `Vec<Item>` into OpenAI Chat Completions
12	/// `messages: [...]` form.
13	///
14	/// Rules per the SMA-316 spec's Wire translation § Chat Completions
15	/// table. Notably:
16	/// - Standalone `Item::ToolCall`s (no preceding `AssistantMessage` in
17	///   the same turn) are gathered into a synthesized
18	///   `{role: "assistant", content: null, tool_calls: [...]}`.
19	/// - `UserMessage` containing `ContentPart::ToolResult` (Anthropic
20	///   nested shape) hoists those parts into top-level `tool` messages.
21	/// - `ContentPart::Image`/`Audio` inside an `AssistantMessage` are
22	///   dropped with `tracing::warn!` (Chat assistant role accepts
23	///   string-or-null only).
24	/// - `ContentPart::Reasoning` is dropped (OpenAI Chat does not accept
25	///   reasoning input).
26	pub(crate) fn to_chat_messages(items: &[Item]) -> Value {
27	    let mut out: Vec<Value> = Vec::new();
28	    let mut pending_tool_calls: Vec<Value> = Vec::new();
29	
30	    fn flush_pending(out: &mut Vec<Value>, pending: &mut Vec<Value>) {
31	        if !pending.is_empty() {
32	            out.push(json!({
33	                "role": "assistant",
34	                "content": Value::Null,
35	                "tool_calls": std::mem::take(pending),
36	            }));
37	        }
38	    }
39	
40	    for item in items {
41	        match item {
42	            Item::System { content } => {
43	                flush_pending(&mut out, &mut pending_tool_calls);
44	                out.push(json!({"role": "system", "content": text_of(content)}));
45	            }
46	            Item::UserMessage { content } => {
47	                flush_pending(&mut out, &mut pending_tool_calls);
48	                emit_user_or_hoist(content, &mut out);
49	            }
50	            Item::AssistantMessage { content, agent: _ } => {
51	                flush_pending(&mut out, &mut pending_tool_calls);
52	                out.push(assistant_message(content));
53	            }
54	            Item::ToolCall {
55	                call_id,
56	                name,
57	                args,
58	            } => {
59	                if let Some(last) = out.last_mut().filter(|m| m["role"] == "assistant") {
60	                    if last["tool_calls"].is_array() {
61	                        last["tool_calls"]
62	                            .as_array_mut()
63	                            .unwrap()
64	                            .push(openai_tool_call(call_id, name, args));
65	                    } else {
66	                        last["tool_calls"] = json!([openai_tool_call(call_id, name, args)]);
67	                    }
68	                } else {
69	                    pending_tool_calls.push(openai_tool_call(call_id, name, args));
70	                }
71	            }
72	            Item::ToolResult { call_id, content } => {
73	                flush_pending(&mut out, &mut pending_tool_calls);
74	                out.push(json!({
75	                    "role": "tool",
76	                    "tool_call_id": call_id,
77	                    "content": text_of(content),
78	                }));
79	            }
80	            _ => {
81	                // Future Item variants (Item is #[non_exhaustive]) — skip with warn.
82	                tracing::warn!(
83	                    target: "paigasus::openai::translate",
84	                    "unknown Item variant; skipping"
85	                );
86	            }
87	        }
88	    }
89	    flush_pending(&mut out, &mut pending_tool_calls);
90	    Value::Array(out)
91	}
92	
93	fn text_of(parts: &[ContentPart]) -> String {
94	    let mut s = String::new();
95	    for p in parts {
96	        if let ContentPart::Text { text } = p {
97	            if !s.is_empty() {
98	                s.push('\n');
99	            }
100	            s.push_str(text);
101	        }
102	    }
103	    s
104	}
105	
106	fn emit_user_or_hoist(content: &[ContentPart], out: &mut Vec<Value>) {
107	    let mut user_parts: Vec<&ContentPart> = Vec::new();
108	    let mut hoisted: Vec<(String, String)> = Vec::new(); // (call_id, text)
109	
110	    for p in content {
111	        match p {
112	            ContentPart::ToolResult { call_id, content } => {
113	                hoisted.push((call_id.clone(), text_of(content)));
114	            }
115	            other => user_parts.push(other),
116	        }
117	    }
118	
119	    if !user_parts.is_empty() {
120	        out.push(user_message(&user_parts));
121	    }
122	    for (call_id, body) in hoisted {
123	        out.push(json!({
124	            "role": "tool",
125	            "tool_call_id": call_id,
126	            "content": body,
127	        }));
128	    }
129	}
130	
131	fn user_message(parts: &[&ContentPart]) -> Value {
132	    // If everything is plain text, emit `content: "..."` (string).
133	    // Otherwise, emit the multimodal parts array.
134	    if parts.iter().all(|p| matches!(p, ContentPart::Text { .. })) {
135	        let mut text = String::new();
136	        for p in parts {
137	            if let ContentPart::Text { text: t } = p {
138	                if !text.is_empty() {
139	                    text.push('\n');
140	                }
141	                text.push_str(t);
142	            }
143	        }
144	        return json!({"role": "user", "content": text});
145	    }
146	    let arr: Vec<Value> = parts
147	        .iter()
148	        .filter_map(|p| match p {
149	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
150	            ContentPart::Image { source } => {
151	                media_url(source).map(|url| json!({"type": "image_url", "image_url": {"url": url}}))
152	            }
153	            ContentPart::Audio { source } => media_url(source)
154	                .map(|data| json!({"type": "input_audio", "input_audio": {"data": data}})),
155	            _ => None,
156	        })
157	        .collect();
158	    json!({"role": "user", "content": arr})
159	}
160	
161	/// Translate a [`MediaSource`] into a URL/data string suitable for OpenAI's
162	/// `image_url.url` or `input_audio.data` fields.
163	///
164	/// Returns `None` for unknown future variants so callers can skip the part
165	/// entirely rather than emitting an empty string into a required field.
166	fn media_url(src: &MediaSource) -> Option<String> {
167	    match src {
168	        MediaSource::Url { url } => Some(url.clone()),
169	        MediaSource::Base64 { mime_type, data } => Some(format!("data:{mime_type};base64,{data}")),
170	        _ => {
171	            tracing::warn!(
172	                target: "paigasus::openai::translate",
173	                "unsupported MediaSource variant; skipping multimodal part"
174	            );
175	            None
176	        }
177	    }
178	}
179	
180	fn assistant_message(content: &[ContentPart]) -> Value {
181	    // Assistant role accepts string-or-null content + sibling tool_calls.
182	    // Hoist nested ToolUse blocks into tool_calls; warn on Image/Audio
183	    // parts (not representable); drop Reasoning.
184	    let mut text = String::new();
185	    let mut tool_calls: Vec<Value> = Vec::new();
186	
187	    for p in content {
188	        match p {
189	            ContentPart::Text { text: t } => {
190	                if !text.is_empty() {
191	                    text.push('\n');
192	                }
193	                text.push_str(t);
194	            }
195	            ContentPart::ToolUse {
196	                call_id,
197	                name,
198	                args,
199	            } => {
200	                tool_calls.push(openai_tool_call(call_id, name, args));
201	            }
202	            ContentPart::Reasoning { .. } => { /* drop */ }
203	            ContentPart::Image { .. } | ContentPart::Audio { .. } => {
204	                tracing::warn!(
205	                    target: "paigasus::openai::translate",
206	                    "dropping multimodal ContentPart from AssistantMessage (Chat assistant role accepts only string content)"
207	                );
208	            }
209	            ContentPart::ToolResult { .. } => {
210	                tracing::warn!(
211	                    target: "paigasus::openai::translate",
212	                    "dropping ContentPart::ToolResult nested in AssistantMessage (only valid on UserMessage in Anthropic shape)"
213	                );
214	            }
215	            _ => { /* future variants */ }
216	        }
217	    }
218	
219	    let content_value = if text.is_empty() && !tool_calls.is_empty() {
220	        Value::Null
221	    } else {
222	        Value::String(text)
223	    };
224	
225	    let mut obj = serde_json::Map::new();
226	    obj.insert("role".to_owned(), Value::String("assistant".to_owned()));
227	    obj.insert("content".to_owned(), content_value);
228	    if !tool_calls.is_empty() {
229	        obj.insert("tool_calls".to_owned(), Value::Array(tool_calls));
230	    }
231	    Value::Object(obj)
232	}
233	
234	fn openai_tool_call(call_id: &str, name: &str, args: &Value) -> Value {
235	    json!({
236	        "id": call_id,
237	        "type": "function",
238	        "function": {
239	            "name": name,
240	            "arguments": args.to_string(),
241	        }
242	    })
243	}
244	
245	/// Translate a conversation `Vec<Item>` into OpenAI Responses-API
246	/// `input: [...]` form.
247	///
248	/// Items become `{type: "message", role, content: [parts]}` blocks for
249	/// system/user/assistant; `Item::ToolCall` becomes a
250	/// `function_call` item; `Item::ToolResult` becomes a
251	/// `function_call_output` item. The same standalone-`ToolCall` rule
252	/// applies — there is no special carrier needed because the Responses
253	/// API treats function_call items as top-level.
254	pub(crate) fn to_responses_input(items: &[Item]) -> Value {
255	    let mut out: Vec<Value> = Vec::new();
256	    for item in items {
257	        match item {
258	            Item::System { content } => {
259	                out.push(json!({
260	                    "type": "message",
261	                    "role": "system",
262	                    "content": [{"type": "input_text", "text": text_of(content)}],
263	                }));
264	            }
265	            Item::UserMessage { content } => {
266	                let mut text_parts: Vec<Value> = Vec::new();
267	                let mut hoisted: Vec<Value> = Vec::new();
268	                for p in content {
269	                    match p {
270	                        ContentPart::Text { text } => {
271	                            text_parts.push(json!({"type": "input_text", "text": text}));
272	                        }
273	                        ContentPart::Image { source } => {
274	                            if let Some(url) = media_url(source) {
275	                                text_parts.push(json!({"type": "input_image", "image_url": url}));
276	                            }
277	                        }
278	                        ContentPart::ToolResult { call_id, content } => {
279	                            hoisted.push(json!({
280	                                "type": "function_call_output",
281	                                "call_id": call_id,
282	                                "output": text_of(content),
283	                            }));
284	                        }
285	                        _ => { /* drop reasoning/audio/future variants */ }
286	                    }
287	                }
288	                if !text_parts.is_empty() {
289	                    out.push(json!({"type": "message", "role": "user", "content": text_parts}));
290	                }
291	                out.extend(hoisted);
292	            }
293	            Item::AssistantMessage { content, agent: _ } => {
294	                let parts: Vec<Value> = content
295	                    .iter()
296	                    .filter_map(|p| match p {
297	                        ContentPart::Text { text } => {
298	                            Some(json!({"type": "output_text", "text": text}))
299	                        }
300	                        _ => None,
301	                    })
302	                    .collect();
303	                if !parts.is_empty() {
304	                    out.push(json!({"type": "message", "role": "assistant", "content": parts}));
305	                }
306	                // Hoist nested ToolUse blocks into top-level function_call items.
307	                for p in content {
308	                    if let ContentPart::ToolUse {
309	                        call_id,
310	                        name,
311	                        args,
312	                    } = p
313	                    {
314	                        out.push(json!({
315	                            "type": "function_call",
316	                            "call_id": call_id,
317	                            "name": name,
318	                            "arguments": args.to_string(),
319	                        }));
320	                    }
321	                }
322	            }
323	            Item::ToolCall {
324	                call_id,
325	                name,
326	                args,
327	            } => {
328	                out.push(json!({
329	                    "type": "function_call",
330	                    "call_id": call_id,
331	                    "name": name,
332	                    "arguments": args.to_string(),
333	                }));
334	            }
335	            Item::ToolResult { call_id, content } => {
336	                out.push(json!({
337	                    "type": "function_call_output",
338	                    "call_id": call_id,
339	                    "output": text_of(content),
340	                }));
341	            }
342	            _ => {
343	                // Future Item variants — skip.
344	                tracing::warn!(
345	                    target: "paigasus::openai::translate",
346	                    "unknown Item variant; skipping in to_responses_input"
347	                );
348	            }
349	        }
350	    }
351	    Value::Array(out)
352	}
353	
