355	mod chat_tests {
356	    use super::*;
357	
358	    fn text(t: &str) -> ContentPart {
359	        ContentPart::Text { text: t.to_owned() }
360	    }
361	
362	    #[test]
363	    fn system_message_is_text_only() {
364	        let items = vec![Item::System {
365	            content: vec![text("be helpful")],
366	        }];
367	        let out = to_chat_messages(&items);
368	        assert_eq!(out, json!([{"role": "system", "content": "be helpful"}]));
369	    }
