371	    #[test]
372	    fn user_message_text_only() {
373	        let items = vec![Item::UserMessage {
374	            content: vec![text("hi")],
375	        }];
376	        let out = to_chat_messages(&items);
377	        assert_eq!(out, json!([{"role": "user", "content": "hi"}]));
378	    }
379	
380	    #[test]
381	    fn user_message_with_image_url_emits_multimodal_parts() {
382	        let items = vec![Item::UserMessage {
383	            content: vec![
384	                text("look:"),
385	                ContentPart::Image {
386	                    source: MediaSource::Url {
387	                        url: "https://example.com/cat.png".to_owned(),
388	                    },
